    fd = os.dup(root_fd)
    for depth, name in enumerate(dirs, 1):
        try:
            child = _open_dir(fd, name, create)
        except OSError as exc:
            where = "/".join(dirs[:depth])
            if exc.errno in (errno.ELOOP, errno.ENOTDIR):
