    except OSError:
        return False


def _open_dir(parent_fd: int, name: str, create: bool) -> int | None:
    while True:
        try:
            return os.open(name, _DIR_FLAGS, dir_fd=parent_fd)
        except FileNotFoundError:
            if not create:
                return None
        try:
            os.mkdir(name, dir_fd=parent_fd)
        except FileExistsError:
